node -e 'const fs = require("node:fs")
const { execFileSync } = require("node:child_process")
const fail = (m) => { console.error(m); process.exit(1) }
let log
try {
  log = execFileSync("git", ["log", "--format=%s", "-n", "400"], { encoding: "utf8" })
} catch (e) {
  console.error("probe could not look: git log is unavailable here")
  process.exit(79)
}
let bl
try { bl = require("./scripts/lib/ledger.mjs").loadBacklog() } catch (e) {
  console.error("probe could not look: the one list is unreadable here")
  process.exit(79)
}
const ids = new Set(bl.entries.map((e) => e.id))
const seen = new Set()
for (const m of log.matchAll(/\b(?:LIVE|PROG|HYG|OWN|DEF|SCAN)-[A-Z0-9]+(?:-[A-Z][A-Z0-9]*)*\b/g)) seen.add(m[0])
if (seen.size === 0) {
  console.error("probe could not look: no backlog id appears in the last 400 commit subjects")
  process.exit(79)
}
const missing = [...seen].filter((i) => !ids.has(i)).sort()
if (missing.length) {
  fail(missing.length + " id(s) shipped in a merged commit and sit on no row of the one list, so a change that reached production is recorded nowhere the list can prove: " + missing.join(", ") + ". check:backlog cannot see this because it iterates the ROWS, and an id that was never added is not a row.")
}
// Patching the holes by hand leaves the hole. A guard nobody wired is the #2098 failure, so
// closing this row means the check RUNS, not that two rows were inserted.
let ci
try { ci = fs.readFileSync(".github/workflows/ci.yml", "utf8") } catch (e) {
  console.error("probe could not look: the CI workflow is unreadable here")
  process.exit(79)
}
if (!/shipped-ids|shipped_ids|commit-ids|check:shipped/.test(ci)) {
  fail("the missing ids were added but no wired guard reads merged commit subjects for ids the one list lacks, so the next shipped-with-no-row change is invisible again.")
}
'
